// French editorial summaries authored from the cited, bounded Markdown passages.
// Passage anchors select exact text; the importer retains every selected excerpt.
// This file is a work-in-progress, NOT a declaration of complete book coverage.
export const BOOK='src-1678b1eb8c4bd691';
export const OUTBACK='src-a3a28719eed85a70';
export const RIFT='src-e76020e4b32da626';
export const ENDGAME='src-c86af6abdc3184c5';
const entry=(sourceId,name,type,summary,content,passages,site,family='WORLD',usage='darkstryder_scenario')=>({sourceId,name,type,summary,content,passages,site,family,usage});
const p=(page,start,end)=>({page,start,end});
const room=(id)=>({kind:'room',id});
const initialEntries=[
  entry(BOOK,'FarStar','Ship','Corvette corellienne transformée en bâtiment d’exploration armé, capturée sur Kal’Shebbol et confiée à Keleman Ciro pour poursuivre le Moff.','### Origines et changements de rôle\nConstruit pour Chandrila près de soixante ans auparavant, le Freedom’s Messenger est d’abord un navire diplomatique. Il accueille l’intégration de la Confédération de Marzoon à la République et transporte des Jedi lors du soulèvement de Vaykaaris. Transformé en bâtiment militaire, il permet une évacuation massive à Ord Torrenze, mais une surcharge du réacteur entraîne sa chute.\n\n### Sous contrôle impérial\nL’Empire récupère l’épave et la remet en service sous le nom de Renegade, avec Kentor Sarne comme commandant. Le navire rejoint plus tard ses forces dans le secteur de Kathol et participe à la répression sur Charis. Sarne le transforme ensuite en explorateur capable de retrouver des artefacts DarkStryder et de soumettre des colonies isolées.\n\n### Capture et mission\nAprès l’assaut républicain sur Kal’Shebbol, Ciro n’a que 28 heures pour terminer la remise en état et recruter l’équipage. Le bâtiment est rebaptisé FarStar. Les espaces de vie servent aussi au stockage ; les couchettes sont partagées et le hangar intérieur, les senseurs perfectionnés et l’équipement bricolé déterminent les contraintes de la mission.',[p(24),p(25,undefined,'## RECENT')],{kind:'ship'}),
  entry(BOOK,'FarStar — senseurs et communications','Equipment','Le FarStar bénéficie de senseurs exceptionnellement sensibles et d’un émetteur subspatial renforcé, au prix d’un encombrement et d’une consommation élevés.','Les nouveaux senseurs doublent presque la portée antérieure et peuvent révéler un adversaire avant que celui-ci ne détecte la corvette. Ils consomment davantage d’énergie et occupent plus de place.\n\nL’émetteur subspatial porte à près de 100 années-lumière, mais ne constitue pas une hyperradio. Les correspondants ordinaires, limités à environ 25 années-lumière, peuvent recevoir sans pouvoir répondre jusqu’au FarStar. L’équipe tente de changer canaux et chiffrement pour éviter la surveillance impériale ; l’écoute du réseau de Sarne reste une possibilité, pas un accès acquis.',[p(25,'## SENSORS','## WEAPONS'),p(26,'## COMMUNICATIONS','## CURRENT')],{kind:'ship'},'RULES','rules'),
  entry(BOOK,'FarStar — vie à bord','Location','Le manque d’espace, les quarts alternés, les équipements bricolés et les restrictions d’énergie mettent l’équipage sous tension.','Les quartiers sont froids et peu éclairés ; seules des zones essentielles restent entièrement alimentées. Les ingénieurs privilégient l’accès rapide aux composants plutôt que l’esthétique : câbles et conduites demeurent visibles. Les réserves de pièces techniques priment sur les vivres, susceptibles d’être obtenus sur les mondes visités.\n\nTrente chambres à deux couchettes doivent accueillir un équipage d’environ 120 personnes grâce au partage des lits entre deux quarts de douze heures. Certains préfèrent dormir sur des tapis au sol. Cette promiscuité fournit des tensions à jouer, sans imposer que des bagarres ou ruptures aient effectivement eu lieu.',[p(27,'## MAKESHIFT'),p(28,'## STORAGE BINS')],{kind:'ship'}),
  entry(BOOK,'FarStar — sabotage informatique de Sarne','Secret','Sarne a caché une balise de position et des routines de sabotage dans les ordinateurs et les interfaces des droïdes.','### Deeplink\nUn programme transmet la position et le cap du FarStar pendant le quart descendant, à une heure aléatoire entre 22 h et 3 h 30. Il reste limité par la portée subspatiale de 100 années-lumière.\n\n### Pièges du système\nLes routines s’activent si l’ordinateur ne reçoit pas le code personnel de Sarne tous les dix jours. Le scénario propose de masquer leurs effets derrière les pannes du matériel bricolé et de révéler leur ampleur progressivement, notamment autour de Shintel Downtime et Crisis.\n\n### Droïdes\nL’interface astromécano peut modifier la programmation d’un R2 ou R3 et provoquer des sabotages : détour d’hyperespace, batteries vidées, eau expulsée. Ce sont des suggestions d’incidents futurs, pas un journal de la partie.',[p(29,'## SARNE'),p(30,'## DROID','## LOCATIONS')],{kind:'ship'},'NARRATIVE'),
  entry(BOOK,'FarStar — hangar et tubes d’amarrage','Location','Le hangar ajouté par Sarne accueille les chasseurs dans un espace saturé ; trois tubes donnent accès au niveau de maintenance.','Les racks TIE n’étaient pas encore installés lors de la capture. Quatre X-wing tiennent dans le hangar, un cinquième sur l’ascenseur ; jusqu’à quatre Defender peuvent être intercalés, mais rendent les mouvements et lancements rapides impossibles. Le grand sas sert notamment au chargement de l’Aegis. Les trois tubes au niveau inférieur peuvent recevoir chacun trois appareils ; les sas terminaux permettent aussi un raccordement entre vaisseaux.',[p(26,'## LANDING','## COMMUNICATIONS')],room('d4-r11')),
  entry(BOOK,'FarStar — dispositif sensoriel supérieur','Location','Une salle circulaire et chaude abrite les principaux équipements de détection et trois opérateurs permanents.','Un noyau d’équipements remplit le centre de la salle ; les consoles et les trois postes sont répartis le long des parois. L’éclairage faible facilite la lecture des écrans et la proximité de l’ingénierie chauffe la pièce. L’antenne rotative alimente les modes passif, scan et recherche. Les relevés sont transmis au contrôle des senseurs et au centre de commandement.',[p(30,'## SENSOR SUITE')],room('d1-r6')),
  entry(BOOK,'FarStar — réacteur principal','Location','Le cœur énergétique occupe quatre ponts de l’ingénierie et alimente tous les grands systèmes du FarStar.','Le réacteur fournit l’énergie aux moteurs, turbolasers, stations de recharge du hangar, communications, senseurs, boucliers, support vital et ordinateurs. Il s’agit d’un ensemble continu traversant plusieurs ponts, non de réacteurs indépendants à chaque niveau.',[p(32,'## MAIN REACTOR','## ENGINE LEVEL')],room('d2-r3')),
  entry(BOOK,'FarStar — contrôle moteurs A','Location','Deux techniciens, un R3 et un droïde énergétique surveillent en permanence les quatre moteurs de la rangée supérieure.','Les techniciens répartissent puissance et refroidissement, synchronisent les moteurs avec les autres niveaux et réalisent la maintenance d’urgence. Les passerelles, grilles et puits ouverts donnent une visibilité et une audibilité entre niveaux. L’environnement est chaud, inconfortable et éclairé en rouge par les écrans et l’éclairage d’urgence.',[p(32,'## ENGINE LEVEL'),p(33,undefined,'## DIRECT')],room('d2-r4')),
  entry(BOOK,'FarStar — répartition directe de puissance','Location','Un technicien permanent répartit l’énergie vers les systèmes autres que les moteurs selon les directives du commandement.','Le poste distribue la puissance aux armes, hangar, ordinateurs, communications, senseurs, boucliers et support vital. Les priorités recommandées par le centre de commandement peuvent obliger à arbitrer entre fonctions essentielles.',[p(33,'## DIRECT','## POWER REGULATION')],room('d2-r5')),
  entry(BOOK,'FarStar — régulation du réacteur','Location','Deux techniciens, trois R3 et un droïde énergétique maintiennent le réacteur ; une défaillance majeure menace tout le vaisseau.','Le poste régule et entretient le cœur énergétique. Une panne catastrophique peut immobiliser le FarStar et provoquer une surcharge explosive du réacteur : c’est un risque décrit par le livre, non une catastrophe déjà survenue.',[p(33,'## POWER REGULATION','## TURBOLASER')],room('d2-r6')),
  entry(BOOK,'FarStar — contrôle informatique','Location','Deux techniciens et quatre R3 entretiennent les ordinateurs centraux de calcul et de stockage.','Les consoles locales préparent et codent leurs données avant de les envoyer ici. Les postes centraux traitent ingénierie, navigation principale et de secours, communications et senseurs. Un diagnostic exige environ une heure par système, indisponible durant l’intervention. La maintenance hebdomadaire prévue est souvent reportée jusqu’à une panne majeure. Le dépôt avant conserve écrans, processeurs et composants de remplacement.',[p(34,'## COMPUTER','## DECK  TWO')],room('d2-r18')),
  entry(BOOK,'FarStar — contrôle moteurs B','Location','Deux techniciens, un R3 et un droïde énergétique surveillent les trois moteurs de la rangée médiane.','Comme au niveau A, le poste permet de redistribuer l’énergie, régler la dissipation thermique, coordonner les moteurs entre niveaux et assurer les interventions d’urgence.',[p(34,'## ENGINE LEVEL')],room('d3-r7')),
  entry(BOOK,'FarStar — contrôle subluminique','Location','Deux ingénieurs permanents coordonnent les moteurs ioniques et équilibrent leur puissance.','Ils ajustent alimentation depuis le réacteur, sortie des moteurs et interface avec les calculateurs de propulsion. Certaines opérations sont télécommandées ; d’autres exigent de ramper dans les accès moteurs.',[p(35,'## SUBLIGHT','## STORAGE')],room('d3-r6')),
  entry(BOOK,'FarStar — contrôle du hangar','Location','Le superviseur de vol et R3-K8 coordonnent atterrissages, départs, amarrages et interventions d’urgence depuis le pont supérieur au hangar.','Le poste est assuré par des rotations de quatre heures prises sur le quart de repos ; un second superviseur rejoint la salle en alerte. R3-K8 possède une voix et communique en Basic. L’hologramme central représente les appareils proches et les écrans montrent tubes et sas. Le superviseur commande l’ascenseur et le champ magnétique, lance les appareils disponibles, déploie secours et sécurité lors d’un crash ou d’un amarrage étranger.',[p(35,'## HANGAR','## CREW')],room('d3-r12')),
  entry(BOOK,'FarStar — mess','Location','Le mess accueille près de quarante personnes et sert également de foyer improvisé entre les repas.','Trois membres hors quart et quatre droïdes SE-4 assurent le service ; la cuisine occupe environ un quart de la salle. Tables de sabacc, discussions et parfois dormeurs occupent le mess lorsque les quartiers sont trop inconfortables ou la salle d’entraînement pleine.',[p(36,'## MESS','## TRAINING')],room('d3-r10')),
  entry(BOOK,'FarStar — salle d’entraînement','Location','Équipements sportifs, tir sur remotes, entraînement martial et jeux offrent un espace de détente à l’équipage.','La salle comprend appareils à gravité variable, petite piste de tir, tapis de combat et cage d’entraînement aux armes de mêlée. Une ligue amicale de combat existe à bord. Le coin salon dispose de deux tables de jeu, coussins, petites tables et holovidéothèque ; il communique avec le mess.',[p(36,'## TRAINING','## LIFEBOAT')],room('d3-r11')),
];

const correctedBindings={
  'FarStar — dispositif sensoriel supérieur':room('d1-r8'),
  'FarStar — réacteur principal':['d2-r5','d3-r4','d4-r3','d5-r5'].map(id=>room(id)),
  'FarStar — contrôle moteurs A':room('d2-r8'),
  'FarStar — répartition directe de puissance':room('d2-r7'),
};
const roomRecords=[
  ['soute supérieure arrière','d1-r11',32,'## REAR TOPSIDE','## FORWARD TOPSIDE','Cette soute froide et sombre contient du matériel de survie.','Masques respiratoires, tentes et lampes sont rangés en caisses. Un poste pris sur le repos couvre les dépôts supérieurs et du pont 1 avec un SE-4. La serrure mécanique se crochette avec un test Facile de sécurité ; l’échec déclenche une sirène audible au pont voisin.'],
  ['soute supérieure avant','d1-r15',32,'## FORWARD TOPSIDE','## DECK  ONE','Le dépôt conserve communications, énergie portable et équipement de terrain.','On y trouve comlinks, cellules, matériel d’escalade, générateurs à fusion, tentes et générateurs de boucliers portatifs. Ces derniers protègent notamment les postes et armes d’une base au sol.'],
  ['turbolaser supérieur','d1-r12',32,'## TURBOLASER','## REAR TOPSIDE','Un artilleur permanent commande la tourelle ; deux techniciens rejoignent leur poste en alerte.','Les techniciens surveillent l’arme supérieure et les armes tribord, puis distribuent leur énergie. Sans eux, précision et alimentation se dégradent. Les réserves autorisent normalement environ cinquante tirs avant recharge ; une recharge complète prend environ cinquante minutes. Les ordres viennent du commandement, qui peut laisser le choix des cibles à l’artilleur en combat.'],
  ['batteries des turbolasers','d2-r11',33,'## TURBOLASER STORAGE',undefined,'Des caissons blindés protègent les batteries qui alimentent les armes.','Chaque caisson accueille trois batteries d’un mètre cube, remplaçables en environ cinq minutes chacune. Leur durée de service recommandée est d’environ trois mille tirs. Le blindage réduit la propagation d’une surcharge, sans protéger une personne placée tout contre une batterie qui explose.'],
  ['dépôt avant du pont 1','d2-r15',34,'## DECK ONE FORWARD','## STORAGE','Matériel de terrain et pièces d’ascenseur ou de turbolaser sont regroupés dans ce grand dépôt.','Comlinks, cellules, matériel d’escalade, générateurs à fusion, tentes et boucliers portatifs côtoient batteries de réserve, convertisseurs, raccords et caissons de batteries.'],
  ['dépôts du pont 1','d2-r16',34,'## STORAGE','## COMPUTER','Deux dépôts conservent les fournitures usuelles, médicales et de survie.','Le contenu comprend médicaments, matériel médical, couvertures, éclairages, intercoms et rustines de coque. Une partie du dépôt tribord a été transformée en réserve alimentaire en vrac.'],
  ['contrôle de l’hyperpropulsion','d3-r5',35,'## HYPERDRIVE','## SUBLIGHT','Les ingénieurs équilibrent les moteurs et assurent l’interface avec les motivateurs et les calculateurs de navigation.','Ils régulent l’alimentation et la puissance de chaque moteur. Certaines réparations nécessitent un accès physique par les passages moteurs. En cas de défaillance majeure, le poste peut reprendre les ordinateurs d’astrogation et arrêter les moteurs pour éviter une surcharge.'],
  ['dépôt technique du pont 2','d3-r3',35,'## STORAGE','## HANGAR','Le dépôt de l’ingénierie conserve des pièces classées pour les propulsions hyperdrive et ionique.','Amortisseurs alluviaux, motivateurs, attaches et câblage sont étiquetés. Des datapads donnent schémas et diagnostics pour accélérer les réparations ; les composants moteurs les plus volumineux ne peuvent pas être emportés en remplacement.'],
  ['quartiers de l’équipage','d3-r9',35,'## CREW',undefined,'Les couchettes se partagent entre les deux quarts ; les logements sont étroits et peu confortables.','Les trois groupes de cinq chambres du pont 2 comportent deux lits par chambre et quatre occupants alternant les quarts. Le manque d’intimité et le partage des lits sont des sources explicites de tension.'],
  ['contrôle des boucliers','d3-r18',37,'## SHIELD','## SENSOR','Un technicien et un R3 distribuent les boucliers sur les quatre orientations selon les ordres du commandement.','Les boucliers à particules restent normalement actifs sauf lors des mouvements de vaisseaux ; ils contribuent à la résistance de coque. Les écrans énergétiques, très consommateurs, sont surtout utilisés en combat et n’arrêtent pas les canons ioniques.'],
  ['contrôle des senseurs','d3-r17',37,'## SENSOR','## CAPTAIN','Un technicien et un R3 coordonnent les deux suites de détection et filtrent les informations pertinentes.','Le poste envoie les relevés au contrôle informatique, les analyse et sélectionne ce qui mérite l’attention de l’officier senseurs, lequel conserve un accès distant aux données brutes.'],
  ['cabine du capitaine','d3-r13',37,'## CAPTAIN','## LIFEBOAT','La cabine sert également de bureau ; elle est un peu plus grande et surtout non partagée.','Bureau, terminal et rangements pour documents et disques complètent un aménagement spartiate. Ciro maintient volontairement chaleur et lumière à bas niveau pour donner l’exemple en matière d’économie d’énergie.'],
  ['contrôle environnemental','d3-r16',37,'## ENVIRONMENTAL','## COMMAND','Le poste assure air, eau, chaleur, éclairage, gravité et compensation des accélérations.','Les convertisseurs reçoivent les flux du recyclage et de l’hydroponie. Des relais répartis dans le vaisseau stabilisent l’environnement. Le système pourrait varier les conditions par compartiment scellé, mais le livre indique qu’aucune zone n’a été ainsi reconfigurée.'],
  ['quartiers d’urgence','d3-r14',38,'## EMERGENCY','## PROBE','Douze membres peuvent se reposer près du commandement lors d’alertes prolongées.','Quatre couchettes doubles et quatre tapis permettent un rappel rapide vers les postes essentiels sans envoyer l’équipage jusque dans les quartiers habituels.'],
  ['contrôle des droïdes sondes','d3-r15',38,'## PROBE','## LIFEBOAT','Deux membres à temps partiel et un R3 permanent préparent les sondes et les drones messagers.','Le poste répare et programme les appareils, lance les reconnaissances, rassemble cartes stellaires, coordonnées et résultats de prospection. Ces données sont accessibles aux ordinateurs d’astrogation et au contrôle informatique.'],
  ['répartition de puissance moteurs','d4-r6',39,'## ENGINE LEVELS','## AUXILIARY','Ce poste distribue l’énergie du réacteur aux onze moteurs ; Lofryyhn y supervise habituellement l’ingénierie.','Deux postes permanents sont renforcés de trois en alerte. Trois R3 suivent et redirigent les flux, quatre droïdes énergétiques fournissent une réserve et un K4 surveille les signes de sabotage. Une panne peut immobiliser la propulsion et provoquer une surcharge.'],
  ['contrôle auxiliaire','d4-r5',39,'## AUXILIARY','## HEAT','Le contrôle auxiliaire peut reprendre les fonctions de postes d’ingénierie ou du commandement endommagés.','Deux opérateurs et un R3 assurent le service permanent ; six postes supplémentaires peuvent être ajoutés lors d’une redistribution majeure. Le contrôle oriente également les deux stations auxiliaires du pont 4.'],
  ['contrôle chaleur et énergie','d4-r4',39,'## HEAT','## CREW','Le poste évacue la chaleur et absorbe les surcharges avant qu’elles n’endommagent un système vital.','Des évents et déflecteurs dissipent dans l’espace la chaleur des moteurs et du réacteur. Des bobines détournent les pics d’énergie, y compris ceux causés par des impacts. Deux techniciens assurent la maintenance à temps partiel et rejoignent immédiatement le poste en alerte.'],
  ['quartiers des officiers','d4-r9',40,'## OFFICERS','## LIFEBOAT','Quatre cabines à deux lits accordent à chaque officier une couchette personnelle, sans alternance de quarts.','Elles sont un peu plus grandes que les logements ordinaires et disposent de rangements, terminaux, liseuses et petits bureaux pour travailler et conserver documents ou souvenirs.'],
  ['salon des officiers','d4-r14',42,'## OFFICERS','## COMMUNICATIONS','Un ancien dépôt sert de salon personnalisé et de salle de réunion de remplacement.','Les non-officiers peuvent entrer mais doivent sortir si un officier le demande. Caisses techniques et souvenirs encombrent la pièce. Parmi les curiosités figurent un casque de stormtrooper troué, un œuf de krayt stérile et une cellule prétendument issue du sabre de Vador : cette dernière attribution est une plaisanterie douteuse de Loh’khar, non un fait établi.'],
  ['communications','d4-r19',42,'## COMMUNICATIONS','## COMMAND','Un technicien permanent, renforcé en alerte, exploite les réseaux de communication et le transcepteur subspatial.','Les calculateurs permettent d’émettre sur les fréquences connues et de rechercher celles de civilisations inconnues. Un ordinateur tente de déchiffrer les communications impériales et chiffre les émissions du FarStar.'],
  ['réparation d’urgence','d4-r18',42,'## EMERGENCY','## LIFEBOAT','Le poste redirige énergie et liaisons informatiques pour maintenir les fonctions vitales après une avarie.','Un poste permanent, quatre postes d’alerte et un R3 peuvent reprendre des contrôles rendus inutilisables ailleurs, mais les performances de ces fonctions de secours sont généralement réduites.'],
  ['recyclage','d4-r17',43,'## RECYCLING','## SCIENCE LAB A','Le recyclage récupère l’air, l’eau et les déchets pour prolonger l’autonomie du bâtiment.','Deux techniciens interviennent à temps partiel. Eau et air purifiés retournent aux réserves et au support vital ; les effluents nutritifs alimentent l’hydroponie. Les matériaux récupérables vont aux ateliers ; les déchets non récupérables sont incinérés dans le réacteur. Une panne obligerait à ravitailler plus souvent.'],
  ['laboratoire A','d4-r15',43,'## SCIENCE LAB A','## SCIENCE LAB B','Un scientifique et deux assistants à temps partiel analysent plantes, animaux et risques biologiques.','Stations de zoologie, botanique, xénobiologie et toxicologie, cages de stase, dissections et calculateurs servent notamment à déterminer la comestibilité et les dangers des organismes rencontrés.'],
  ['laboratoire B','d4-r16',43,'## SCIENCE LAB B','## LIFEBOAT','Un scientifique et deux assistants analysent géologie, atmosphère, météorologie, océans, chimie et phénomènes spatiaux.','Les scanners recherchent toxicité et usages possibles des échantillons, notamment pour fabriquer des pièces. Le laboratoire examine aussi astéroïdes, poussières, nébuleuses et étoiles à partir des relevés du navire.'],
  ['contrôle moteurs C','d5-r9',43,'## ENGINE LEVEL C','## AUXILIARY','Deux techniciens, un R3 et un droïde énergétique surveillent les quatre moteurs inférieurs.','Le poste coordonne ces moteurs avec les autres niveaux, règle alimentation et dispersion thermique et permet les interventions d’urgence.'],
  ['armurerie','d5-r4',44,'## ARMORY','## MACHINE','L’armurerie conserve les armes collectives sous garde d’un K4 ; les armes personnelles sont soumises à l’autorisation du capitaine.','Un membre de l’équipage assure le poste à temps partiel. La serrure électronique exige un test Modéré de sécurité ; un échec alerte la sécurité au commandement. Blasters, armes lourdes, munitions, grenades et protections constituent un stock initial de scénario, pas les quantités restantes de ta partie.'],
  ['atelier mécanique','d5-r10',44,'## MACHINE','## MAIN BATTERIES','L’atelier de Lofryyhn fabrique des pièces mécaniques mais pas les circuits ou puces sophistiqués.','Deux postes à temps partiel, un treadwell et trois R3 usinent des pièces pour moteurs, véhicules et chasseurs à partir des plans informatiques. Les composants électroniques doivent provenir des réserves ou être achetés sur un monde équipé.'],
  ['batteries principales','d5-r6',44,'## MAIN BATTERIES','## RESERVE','Les batteries principales assurent une alimentation de secours limitée lorsque le réacteur tombe en panne.','Elles offrent environ six heures sans turbolasers ni hyperdrive. Un saut et deux heures d’hyperespace peuvent épuiser la réserve. La recharge demande six heures si toute l’énergie y est consacrée, douze avec les fonctions normales non combattantes maintenues.'],
  ['batteries de réserve','d5-r7',44,'## RESERVE','## BULK','Les batteries de réserve sont plus encombrantes et moins efficaces que les principales.','Elles assurent environ quatre heures de puissance ordinaire, ou un saut et quarante-cinq minutes d’hyperespace avant retour forcé dans l’espace réel.'],
  ['chambre froide','d5-r11',44,'## BULK','## STORAGE','La plupart des vivres sont stockés en vrac dans ce compartiment organisé par R-97.','Des bacs réfrigérés préservent les denrées périssables ; les autres aliments sont traités pour durer. Un SE-4 reste sur place. L’agencement des caisses paraît labyrinthique aux organiques mais facilite la répartition des ressources par le droïde.'],
  ['entrepôt du pont 4','d5-r12',44,'## STORAGE',undefined,'Le plus grand dépôt contient un éventail de fournitures emportées en vrac.','Puces, uniformes, graines, tapis de couchage, médicaments, bacta, pièces de répulseur et cellules de blaster y sont stockés. Ce stock de départ ne représente pas un inventaire actuel de partie.'],
  ['maintenance des véhicules','d5-r14',45,'## MAINTENANCE','## DOCKING','Le principal atelier de réparation stocke véhicules terrestres et pièces de chasseurs ou de navettes.','Un mécanicien, des assistants, deux R3 et trois treadwells travaillent au milieu des composants. T’achak y modifie les véhicules. L’ascenseur permet d’envoyer les pièces au hangar : les X-wing et navettes ne descendent pas à ce niveau, contrairement aux Defender.'],
  ['réparation des droïdes','d5-r15',45,'## DROID','## FRESH','Quatre grandes stations entretiennent les droïdes sous la direction de DD-19 et de l’assistant SE-4-I7.','Un technicien permanent et des renforts disposent de membres, cerveaux, vocabulaires et composants. Les droïdes traitent les techniciens organiques comme des intrus simplement tolérés.'],
  ['réservoirs d’eau','d5-r13',45,'## FRESH',undefined,'Douze réservoirs indépendants réduisent les conséquences d’une contamination ou d’une perforation de coque.','Chaque cuve possède sa propre alimentation et des cloisons internes limitent le ballottement. L’eau perd sa fraîcheur après quelques semaines ; son renouvellement est prioritaire lors d’un atterrissage sur un nouveau monde.'],
  ['hydroponie A','d5-r17',46,'## HYDROPONICS','## LOWER','Les cultures hydroponiques complètent les provisions et fournissent des aliments frais.','Le laboratoire A simule un climat tempéré, le B un milieu tropical chaud et humide. Chaque laboratoire compte deux postes à temps partiel ; les trois droïdes ouvriers Roche J9 participent aux cultures, capables d’en assurer seuls l’exploitation sous supervision.'],
  ['dispositif sensoriel inférieur','d6-r6',46,'## SENSOR','## BELLY','Un opérateur assure les senseurs de précision et les antennes de communication.','Le mode focus dépend aussi du dispositif supérieur pleinement opérationnel. Le poste fournit les données de visée ; sans opérateur, les attaques de turbolasers subissent une difficulté accrue. Les communications externes requièrent également sa présence.'],
  ['soute inférieure arrière','d6-r8',46,'## BELLY','## FORWARD','Vivres et pièces de senseurs, turbolasers, chasseurs et navettes sont rangés dans cette soute.','Un SE-4 aide R-97 à garder l’ordre. Matériel de survie et fournitures diverses s’accumulent ; une pièce introuvable ailleurs peut encore être enfouie dans une caisse de ce dépôt.'],
  ['soute inférieure avant','d6-r17',46,'## FORWARD','## TURBOLASER','Cette soute rassemble vivres, pièces d’hydroponie, support vital et droïdes de récupération.','Lampes, conduites, graines, pompes, éléments de gravité et échangeurs thermiques côtoient plusieurs vieux R3 partiellement démontés. Un SE-4 est présent en permanence.'],
  ['turbolaser inférieur','d6-r9',46,'## TURBOLASER','## ESCAPE','La tourelle inférieure dispose d’un artilleur permanent et de deux postes techniques activés en alerte.','Les techniciens installés entre le pont 4 et le pont d’armes inférieur surveillent et alimentent cette arme ainsi que les deux turbolasers bâbord du pont 1.'],
];
const crew=(id)=>id?{kind:'crew',id}:undefined;
const biographies=[
  entry(BOOK,'Keleman Ciro','Character','Ancien étudiant de Dolomar devenu résistant puis commando, Ciro commande le FarStar grâce notamment à sa résistance aux effets mentaux DarkStryder.','Sur Dolomar, Ciro délaisse une carrière de programmeur pour la résistance qui renverse le gouverneur impérial. Il rejoint la Nouvelle République, se distingue dans le secteur de Brak et entre chez les Commandos de Page ; Noell, son frère, choisit le corps des pilotes.\n\nRéservé mais ferme, Ciro écoute les avis puis exige l’exécution rapide des ordres. Il fait confiance à ses compétences, surtout informatiques, mais ne possède pas encore l’expérience d’un commandant de grand équipage. Page voit dans sa résistance mentale un atout pour la mission.',[p(48,'## CAP T','## ■')],crew('DIR-KC')),
  entry(BOOK,'Kaiya Adrimetrum','Character','Veuve à la suite de l’occupation impériale de Siluria III, Kaiya devient cheffe de résistance, combattante de l’Alliance et premier officier du FarStar.','Après la mort de son mari, Kaiya rassemble parents et amis en cellule de résistance et attaque le gouverneur de Siluria III. Corwin Shelvay la recrute pour l’Alliance. Son efficacité finit par lui ouvrir les Commandos de Page.\n\nElle inspire une loyauté personnelle forte et protège son unité, tout en acceptant les risques du combat. Son calme apparent masque une fatigue et des doutes sur le poids du commandement. Elle complète le style réservé de Ciro par une fermeté capable de devenir agressive lorsque la mission ou ses proches sont menacés.',[p(49,'## KAIYA','## ■')],crew('DIR-KA')),
  entry(BOOK,'Gorak Khzam','Character','L’officier de sécurité rodien cache son passé de responsable des Sabiador Slavers et embarque pour échapper à d’anciens esclaves.','Khzam se présente comme un commerçant connaissant les mondes de Kathol. Il évite le contact physique et les espèces anciennement asservies. En secret, il dirigeait la sécurité d’un groupe qui fournissait des esclaves aux arènes de Sarne ; ce groupe s’est dispersé.\n\nIl accepte mensonge et meurtre discret pour protéger son identité et recherche un refuge possible. Jessa Dajus connaît son passé, mais Khzam connaît aussi le véritable rôle qu’elle jouait chez Sarne. Il chasse avec Kl’aal, dont l’amitié pourrait changer si ses motivations étaient dévoilées.',[p(50,'## SECURITY','## ■')],crew('TAC-GK')),
  entry(BOOK,'Darryn Thyte','Character','Ancien pilote mutilé à Vaenrood, Thyte maîtrise navigation, senseurs et communications mais vit mal sa réaffectation à la passerelle.','Un crash causé par l’artillerie impériale lui coûte main et bras droits. Sa prothèse rudimentaire permet une interface informatique mais manque de finesse. Retiré du pilotage, il exige son transfert au FarStar pour prouver sa valeur.\n\nThyte considère la passerelle comme son territoire et tolère mal l’ingérence. Son expertise d’astrogateur rend son attitude difficile à sanctionner. Il désire reprendre le vol mais souffre d’un manque de confiance ; Gorjaye refuse de l’affecter aux chasseurs, ce qui nourrit sa rancœur.',[p(51,'## LIEUTENANT DARRYN','## ■')],crew('NAV-DT')),
  entry(BOOK,"Loh'khar the Finder",'Character','Le spécialiste twi’lek de l’approvisionnement exploite réseaux, information et chantage ; Sarne a confisqué son transport sur Kal’Shebbol.','Loh’khar dit avoir quitté Ryloth à cause d’une conspiration de clan, version non confirmée. Marchand itinérant puis intermédiaire d’astroports, il construit des réseaux d’agents, espions et voleurs pour trouver marchandises rares ou illégales. Trois Turazza issus d’œufs obtenus en échange d’informations deviennent ses auxiliaires.\n\nAprès la confiscation de son appareil par Sarne, il commerce sur Kal’Shebbol. Page refuse d’abord son recrutement ; sa capacité à trouver rapidement des condensateurs de turbolaser lui ouvre finalement le FarStar. Il cultive les faveurs, secrets et moyens de pression tout en affichant une façade d’homme d’affaires respectable.',[p(54)],crew('RES-Lo')),
];
const riftCrew=[
  ['Kaiya Adrimetrum','DIR-KA',18,'## KAIYA','## LIEUTENANT DARRYN','Kaiya prend confiance dans le commandement mais exige des explications de Jessa sur son ancien grade.','Le livre recommande sa survie jusqu’au dénouement et utilise Rogue Elements pour ébranler ses certitudes. Les projets de vengeance de Dajus, Kl’aal et Qesya compliquent la préparation d’une bataille contre Sarne dont les forces restent inconnues.'],
  ['Darryn Thyte','NAV-DT',18,'## LIEUTENANT DARRYN','## LIEUTENANT JESSA','La rudesse de Thyte commence à s’atténuer et un attachement à Gorjaye se développe.','Son amertume de pilote privé de vol subsiste. Le livre n’impose plus de rôle décisif à Thyte, mais encourage à le maintenir impliqué dans la mission.'],
  ["Loh'khar the Finder",'RES-Lo',19,"## LOH'KHAR",'## LiEUTENANT','Loh’khar prépare une désertion profitable avec Khzam et cherche à faire réparer un cargo qui lui servira de véhicule de fuite.','Dans Harm’s Way, il défend l’utilité d’un YT-1300 endommagé afin que Brophar et Lofryyhn le remettent en état. Il compte partir avec Rizzal et Vizzal, retrouver la source de DarkStryder et partager les bénéfices avec Khzam. Le moment de son départ reste ouvert et ses bons rapports avec l’équipage servent aussi ce plan.'],
  ['Ranna Gorjaye','PRI-WG',19,'## LiEUTENANT',undefined,'Gorjaye développe une amitié potentiellement amoureuse avec Thyte et un respect réticent pour Kaiya.','Elle partage des parties de sabacc avec Thyte et Dasha, tout en restant solitaire. Elle réprime les critiques contre le commandement même lorsqu’elle les comprend. Une promotion et le choix d’une affectation sont envisagés seulement si ses performances et la survie du FarStar le permettent.'],
  ["Kl'aal",'INT-Kl',20,"## KL'AAL",'## SERGEANT','Le Rift exacerbe l’impatience de Kl’aal, employé à la sécurité après la défection de Khzam.','Il répond à Kaiya et Scoryn sans reprendre entièrement le poste de Khzam. Rogue Elements doit opposer son devoir au commandement à son désir de combattre. S’il tue des mutins, le livre suggère sa révocation de la sécurité et son retour à l’éclairage.'],
  ['Brophar Tofarain','TRA-BT',20,'## SERGEANT','## LOFRYYHN','Brophar supporte mal le vol du Muvon par Khzam ; la réparation du futur Muvon II peut lui redonner un objectif.','D’ordinaire extraverti et apprécié, il devient irritable. La remise en état du YT-1300 trouvé dans Harm’s Way est prévue comme une activité absorbante, éventuellement après quelques encouragements.'],
  ['Lofryyhn','MOT-Lo',20,'## LOFRYYHN','## DASHA','Lofryyhn s’épuise à maintenir le FarStar et reste furieux que l’ancien esclavagiste Khzam ait échappé à l’équipage.','Il doit aider discrètement Brophar à réparer le Muvon II. Si l’alliance entre Loh’khar et Khzam est découverte, sa haine des esclavagistes fournit un conflit majeur, sans résultat imposé à la partie.'],
  ['Dasha Defano','SCO-DD',20,'## DASHA','## COBB','Dasha reste proche de Gorjaye mais se rapproche de Thanis, dont les griefs contre Scoryn l’influencent.','Thanis se présente comme une victime ayant besoin d’écoute. Leur lien n’est pas encore amoureux, même si le livre laisse cette possibilité ouverte. Dasha devrait plutôt soutenir Kaiya lors de la mutinerie, malgré un éloignement progressif de Gorjaye.'],
  ['Cobb Unser','TRA-CU',20,'## COBB','## KRUDAR','Retrouver sa sœur réduit la motivation personnelle de Cobb à poursuivre la mission.','Il voudrait pouvoir partir mais reste dépendant des possibilités de transport. Le choix de sa sœur de demeurer à bord devrait l’inciter à rester également.'],
  ['Krudar','TUR-Kr',20,'## KRUDAR',undefined,'L’impatience et les bagarres placent Krudar au bord d’une sanction disciplinaire.','Une nouvelle altercation peut lui coûter son poste et le confiner à ses quartiers. Le MJ peut éprouver sa maîtrise de soi par des provocations ; ces scènes sont des propositions, pas des incidents obligatoires.'],
  ['Boom','INT-Bo',21,'## BOOM','## RIZZAL','Les expériences pyromanes de Boom deviennent un irritant majeur pour l’équipage.','Krudar, qui a soutenu son embarquement, les supporte particulièrement mal. Le livre propose d’utiliser Boom pour accroître ses tensions et mettre sa patience à l’épreuve.'],
  ['Brandis Turgah','DRO-BT',21,'## BRANDIS','## GUNTHAR','Turgah espionne pour les Bothans sous la menace et profite du projet Lifeline pour envoyer ses rapports.','Il craint autant ses employeurs que la réaction des compagnons. Le livre prévoit qu’un message clandestin soit découvert ; refusant de dénoncer les Bothans, il peut être pris pour un agent impérial et emprisonné par Kaiya. Ce déroulement est une direction de scénario, pas un état de captivité déjà appliqué.'],
  ['Gunthar','SEC-Gu',21,'## GUNTHAR','## TANNER','L’intelligence de Gunthar augmente à l’approche de son peuple, dont il partage une conscience collective.','Son éloignement de l’esprit-ruche explique ses difficultés cognitives. Dans Home, il doit retrouver les siens ; des phrases plus complexes apparaissent avant l’arrivée mais ses facultés complètes ne reviennent qu’après la réunion physique.'],
  ['Tanner Carzyn','TUR-TC',21,'## TANNER','## QESYA','Tanner croit trouver en Turgah emprisonné un allié favorable à l’Empire.','Turgah peut manipuler le jeune homme pour se tenir informé. Le livre réserve à leur relation un rôle important dans Endgame et recommande de préserver Tanner pendant le Rift.'],
  ["Qesya Vth'naar",undefined,21,'## QESYA','## SCORYN','Qesya s’inquiète de l’évolution inexpliquée de Gunthar, au point d’être détournée de sa grossesse prochaine.','Ses regards fixés sur l’espace et ses réponses parfois complètes la préoccupent. Elle reste près de lui ; Home doit développer leur rôle dans la campagne.'],
  ['Gammer Firdaaz','ENV-GF',22,'## "GAMMER"','## GENNA','Le livre prévoit que Gammer reste sur Demonsgate pour entretenir le relais à travers le Rift.','En dehors de ce rôle dirigé dans la dernière aventure du tome, son évolution demeure libre pour le MJ.'],
  ['Genna Seedar','MED-GS',22,'## GENNA','## VEGATH','Genna souffre des tensions de l’équipage et peut les signaler directement à Kaiya, qu’elle admire.','Durant Rogue Elements, devoir soigner des mutins ayant blessé les loyalistes crée un conflit professionnel et moral à jouer plutôt qu’à résoudre automatiquement.'],
  ['Vegath Tist','LAB-VT',22,'## VEGATH','## THANIS','Le tome recommande de préserver Vegath pour son rôle dans le supplément final.','Aucune évolution supplémentaire n’est imposée ici ; le MJ conserve une marge de développement personnel.'],
  ['Thanis Gul-Rah','INT-TG',22,'## THANIS','## GAELIN','Thanis voit la promotion de Scoryn comme une menace et cherche un soutien parmi les pilotes.','Scoryn connaît son implication dans la mort du mari de Kaiya. Il entretient les dissensions pour renforcer sa position, tout en étant tenté de l’éliminer. Leur confrontation finale est réservée au tome suivant.'],
  ['Gaelin',undefined,22,'## GAELIN','## BRESLIN','Les compétences informatiques de Gaelin pourraient servir les Bothans ou Turgah.','Le livre propose une tentative de corruption par les contacts bothans de Turgah, sans imposer qu’elle aboutisse.'],
  ['Breslin Drake',undefined,22,'## BRESLIN','## VAREL','Drake peut devenir un atout de contre-espionnage malgré l’impopularité de sa surveillance.','Il soupçonne Turgah et représente un candidat probable à la découverte de ses transmissions clandestines.'],
  ['Varel DeVay',undefined,22,'## VAREL','## MAKEZH','La formation xénobiologique de DeVay pourrait aider l’équipage dans les prochaines rencontres.','Le livre laisse au MJ la liberté de développer son rôle.'],
  ['Makezh',undefined,22,'## MAKEZH',undefined,'Le navigateur formé par les Aing-Tii est essentiel à la traversée du Rift mais devient plus instable.','Cauchemars et hallucinations augmentent avec la progression. Il tente maladroitement de copier uniforme, coupe de cheveux et protocole militaires ; Kaiya reconnaît cet effort malgré ses erreurs.'],
];
const endgameCrew=[
  ['Kaiya Adrimetrum','DIR-KA',21,'## KAIYA','## LIEUTENANT DARRYN','L’approche du domaine de Sarne et la mort prévue de Ciro accroissent la nervosité de Kaiya.','Le livre recommande sa présence parmi les premiers groupes débarqués et son isolement du FarStar pendant Ambush!. Elle peut progressivement reconnaître DarkStryder comme une menace plus grande encore que Sarne.'],
  ['Jessa Dajus','PAS-JD',22,'## LIEUTENANT JESSA',"## LOH'KHAR",'Le passé de colonel et de spécialiste du chantage de Jessa explique sa connaissance des rivaux politiques de Sarne.','Jessa veut confronter DarkStryder pour mettre fin aux cauchemars mais reste tentée par sa technologie. Le livre recommande sa survie ; l’arbitrage entre ambitions, loyauté impériale et respect de Kaiya appartient au joueur et au MJ.'],
  ["Loh'khar the Finder",'RES-Lo',22,"## LOH'KHAR",'## LIEUTENANT RANNA','Loh’khar attend une occasion de déserter pour retrouver Khzam et récupérer les artefacts.','La bataille spatiale ou l’arrivée des Skandrei peuvent couvrir sa fuite, éventuellement à bord du Muvon II avec les Turazza. Le livre suggère un retour opportuniste lors du dénouement et une vente à un émissaire du Soleil Noir dans le Minos Cluster ; la fiabilité des appareils au-delà du Rift risque de ruiner ce projet.'],
  ['Ranna Gorjaye','PRI-WG',22,'## LIEUTENANT RANNA',"## KL'AAL",'L’attachement entre Gorjaye et Thyte reste agité par leurs tempéraments et son goût du risque.','Sous réserve de sa survie jusque-là, le livre laisse désormais les développements libres au joueur et au MJ.'],
  ['Brophar Tofarain','TRA-BT',23,'## SERGEANT','## LOFRYYHN','Le Muvon II réparé rend Brophar plus heureux, mais sa propriété l’oppose à Loh’khar.','Un vol du cargo par le Twi’lek peut le pousser à poursuivre les fugitifs jusque sur la planète. Le reste de son développement est libre.'],
  ['Lofryyhn','MOT-Lo',23,'## LOFRYYHN','## DASHA','La trahison de Loh’khar et son alliance avec Khzam peuvent déclencher la colère de Lofryyhn.','Il veut achever la mission malgré la fatigue et peut chercher à retrouver Loh’khar pour régler l’affaire. Le résultat de la confrontation n’est pas fixé.'],
  ['Dasha Defano','SCO-DD',23,'## DASHA','## COBB','Dasha peut reprendre le commandement des chasseurs si Gorjaye n’est plus en mesure de l’assurer.','Ses liens avec Thanis influencent son regard sur Kaiya, même si la position du chasseur de primes pendant la mutinerie a ébranlé sa confiance. Son évolution reste ouverte.'],
  ['Cobb Unser','TRA-CU',23,'## COBB','## KRUDAR','Ses compétences rudimentaires de pilotage pourraient servir pendant la bataille finale.','Le livre évoque sa mort ou sa capture comme probables, sans les établir comme des faits : le sort réel reste à jouer.'],
  ['Krudar','TUR-Kr',23,'## KRUDAR','## BOOM','Krudar peut être utile dans les affrontements au sol comme dans la bataille spatiale.','Le livre envisage sa perte avec le FarStar mais laisse au MJ et au joueur le développement du personnage ; aucune mort n’est enregistrée dans l’état de campagne.'],
  ['Brandis Turgah','DRO-BT',23,'## BRANDIS',undefined,'Turgah emprisonné veut utiliser Tanner pour transmettre les coordonnées du FarStar aux Bothans.','Il indique l’emplacement d’un ordinateur de chiffrement caché dans ses anciens quartiers et cherche à dicter un message. Son espoir que les précédents rapports aient traversé le Rift demeure incertain.'],
  ['Tanner Carzyn','TUR-TC',24,'## TANNER','## SCORYN','Tanner peut être persuadé de transmettre pour Turgah ce qu’il croit être un message destiné aux Impériaux.','S’il accepte malgré sa peur d’accéder au réseau, les coordonnées partent vers une armada bothane proche juste avant l’entrée dans le système binaire. C’est une branche conditionnelle du scénario.'],
  ['Scoryn','SEC-Sc',24,'## SCORYN','## GENNA','La querelle entre Scoryn et Thanis peut aboutir à une confrontation finale sur la planète.','Le livre évoque un règlement de comptes mais laisse son développement et son issue ouverts.'],
  ['Vegath Tist','LAB-VT',24,'## VEGATH','## THANIS','Vegath doit accompagner l’équipe débarquée ; des habitants peuvent le prendre pour une création supérieure de DarkStryder.','Il pourrait rester comme invité honoré des Yapi et chercher un pouvoir Ta-Ree capable de guérir son addiction au sel. Ce séjour et cette guérison restent des possibilités.'],
  ['Thanis Gul-Rah','INT-TG',24,'## THANIS','## GAELIN','Thanis est rongé par son rôle dans la mort du mari de Kaiya et reporte sa culpabilité sur Scoryn.','Il envisage de l’attaquer dans un endroit isolé sur la surface ; ce passage décrit une intention et une proposition de scène, pas un meurtre accompli.'],
  ['Gaelin',undefined,24,'## GAELIN','## BRESLIN','Gaelin pourrait contribuer au stratagème permettant à Turgah de contacter les Bothans.','Le livre envisage sa participation à la tromperie de Tanner mais laisse le personnage librement développable.'],
  ['Breslin Drake',undefined,24,'## BRESLIN','## CAPTAIN','L’expérience de Drake peut aider à préparer embuscades et raids contre DarkStryder.','Au-delà de cette utilité tactique, aucun destin particulier n’est imposé au personnage.'],
  ['Keleman Ciro','DIR-KC',24,'## CAPTAIN',undefined,'Endgame prévoit la mort de Ciro des suites de ses blessures avant l’arrivée dans le système de DarkStryder.','Le capitaine est décrit comme catatonique depuis son sauvetage de captivité impériale. Cette mort appartient au déroulement original prévu ; elle ne modifie pas son statut dans ta campagne.'],
];
const development=(sourceId,records)=>records.map(([name,id,page,start,end,summary,content])=>entry(sourceId,name,'Character',summary,'### Évolution prévue dans le supplément\n'+content,[p(page,start,end)],crew(id)));
const additionalRooms=[
  entry(BOOK,'FarStar — centre de commandement','Location','Le centre de commandement occupe deux niveaux et rassemble huit postes permanents et quatre postes d’alerte.','### Organisation\nLe niveau supérieur accueille le capitaine, la conduite du vol et les opérations tactiques. Au niveau inférieur se trouvent propulsion subluminique, hyperdrive, boucliers, communications et coordination informatique. Des renforts d’alerte assistent senseurs, ressources, ingénierie et armes.\n\n### Ambiance et sécurité\nÉcrans, passerelles, marches et grande baie frontale occupent un espace surchargé. Trois R3 traitent les données principales et des interfaces supplémentaires permettent l’assistance à la navigation. Deux K4 gardent les accès. Le puits relie plusieurs niveaux techniques et de stockage.',[p(37,'## COMMAND'),p(38,undefined,'## EMERGENCY')],['d3-r19','d4-r20'].map(room)),
  entry(BOOK,'FarStar — infirmerie','Location','Akanseh, ses assistants et trois droïdes 2-1B disposent d’une infirmerie chaude et bien éclairée.','Trois soignants restent disponibles. Dix lits de convalescence, quatre postes de premiers secours, deux cuves bacta et une salle d’opération scellée composent l’équipement initial. Si l’infirmerie déborde, des quartiers voisins accueillent les patients et leurs occupants sont déplacés. La qualité du chauffage, de l’éclairage et des repas inspire des plaisanteries sur l’envie d’être malade.',[p(39,'## SICK'),p(40,undefined,'## OFFICERS')],room('d4-r13')),
  entry(BOOK,'FarStar — salle des pilotes','Location','Les pilotes de service attendent ici lorsqu’ils ne sont pas au hangar ou en patrouille.','Projecteur holographique, écrans de suivi et liaisons avec hangar et commandement présentent tactiques et ordres de Gorjaye. Le contingent initial comporte huit X-wing et quatre Defender, avec six pilotes par quart. Deux assurent la patrouille et quatre attendent ; en alerte, tous doivent rejoindre le briefing sous deux minutes. Ces effectifs de départ ne remplacent pas tes affectations personnalisées.',[p(40,'## PILOT'),p(41,undefined,'## LANDING')],room('d4-r10')),
  entry(BOOK,'FarStar — salle tactique','Location','La salle tactique sert à la stratégie, aux réunions et à l’analyse holographique.','Deux postes pris sur le repos et un R3 exploitent des panneaux plastex et une table holographique centrale d’environ trois mètres. Les affichages réunissent risques de navigation, orbites, situation technique, affectations et énergie. La faible lumière et les lueurs rouges ou vertes lui donnent une ambiance inquiétante.',[p(42,'## TACTICS'),p(43,undefined,'## RECYCLING')],room('d4-r12')),
  entry(BOOK,'FarStar — contrôle auxiliaire secondaire','Location','Deux stations secondaires peuvent absorber une partie du travail d’un poste surchargé ou reprendre un poste défaillant.','Le contrôle auxiliaire principal dirige ces stations. Elles partagent deux techniciens permanents et un R3 ; quatre membres supplémentaires les renforcent en alerte. Elles ne sont pas des postes de commandement indépendants en fonctionnement normal.',[p(43,'## AUXILIARY'),p(44,undefined,'## ARMORY')],room('d5-r8')),
  entry(BOOK,'FarStar — hydroponie B','Location','Le laboratoire B reproduit les conditions tropicales pour cultiver des aliments frais.','Chaleur et humidité distinguent ce laboratoire du milieu tempéré du laboratoire A. Deux postes à temps partiel et les droïdes Roche J9 participent à l’exploitation, complétant les provisions conservées du bâtiment.',[p(46,'## HYDROPONICS','## LOWER')],room('d5-r18')),
  entry(BOOK,'FarStar — capsules de sauvetage','Location','Huit capsules prévues dans le livre accueillent chacune quatre personnes et trois semaines de provisions.','Elles fonctionnent sur le même principe que les canots du bâtiment. La source donne une capacité et des réserves initiales, mais ne permet pas d’inventer leur utilisation ou leur disponibilité actuelle.',[p(46,'## ESCAPE')],['d6-r11','d6-r13'].map(room)),
  entry(BOOK,'FarStar — canots de sauvetage','Location','Le livre décrit des canots de douze ou vingt places, équipés pour trois semaines de survie.','Le canot de vingt places emporte air, eau, vivres, armes de chasse, tentes, matériel médical et un signal de détresse subspatial. Il dispose du carburant nécessaire au lancement et à quelques corrections, puis atterrit par jets de freinage et parachute. Une alarme informe la passerelle, qui peut bloquer le lancement. D’autres canots sont donnés à douze places : les nombres et regroupements du plan local ne sont pas modifiés automatiquement.',[p(36,'## LIFEBOAT'),p(37,'## LIFEBOAT','## ENVIRONMENTAL'),p(40,'## LIFEBOAT','## PILOT')],['d3-r20','d4-r21'].map(room)),
  entry(BOOK,'FarStar — quartiers partagés et sanitaires','Location','Les chambres spartiates offrent peu d’espace personnel et sont associées à des sanitaires communs.','Chaque membre dispose d’un petit casier ; placard, lits et terminaux sont partagés. Les couchettes alternent entre quarts et gardent la chaleur du précédent dormeur, facteur de malaise et de baisse du moral selon le livre. Certains dorment au sol. La source ne détaille pas séparément l’équipement des douches.',[p(35,'## CREW'),p(36,undefined,'## MESS'),p(39,'## CREW','## SICK')],['d3-r8','d4-r7','d4-r8'].map(room)),
  entry(BOOK,'FarStar — postes de tir latéraux','Location','Les petites tourelles du pont 1 sont occupées en alerte et dépendent des stations techniques des grandes tourelles.','Chaque arme dispose d’un artilleur lors des alertes. La maintenance hebdomadaire vérifie circuits, alimentation, éléments optiques, canons et engrenages. Les stations supérieures suivent les armes tribord ; les stations inférieures suivent les armes bâbord.',[p(33,'## TURBOLASER (4)','## TURBOLASER STORAGE')],room('d2-r12')),
  entry(BOOK,'FarStar — alimentation et contrôle des turbolasers','Location','Générateurs, batteries et distribution depuis le réacteur alimentent les armes, sous contrôle de techniciens.','Une partie de la supervision technique et de la répartition de puissance se trouve aux grandes tourelles, avec relais vers les armes latérales. Les générateurs reconstituent la réserve après les tirs ; puiser dans le réacteur peut imposer de réduire propulsion ou boucliers. Le livre ne donne pas ici une description séparée pour chacun des emplacements du plan local.',[p(32,'## TURBOLASER','## REAR TOPSIDE')],['d2-r10','d2-r13'].map(room)),
];
const planet=(sourceId,name,id,summary,content,passages)=>entry(sourceId,name,'Planet',summary,content,passages,{kind:'entity',id});
const worlds=[
  planet(BOOK,"Kal'Shebbol",'place-kal-shebbol','Capitale du secteur de Kathol, colonisée par des Twi’leks fugitifs puis transformée en centre du pouvoir de Sarne.','### Colonisation et société\nDes esclaves twi’leks évadés s’installent quatre siècles auparavant sur les plaines humides. Ils développent agriculture et élevage des chollas. Les nouveaux arrivants doivent être adoptés par un clan ; le relais commercial devient une grande place de négoce. Sa proximité relative avec l’espace républicain motive son choix comme capitale.\n\n### Empire et libération\nLes préfets impériaux remplacent l’autonomie des clans et cités. Sarne nationalise les industries, contrôle les déplacements et réprime les cultures. Au début de la campagne originale, la gouverneure elomin Monjai construit un gouvernement provisoire et une défense à partir des moyens survivants ; l’arrivée d’une flotte républicaine est annoncée, pas déjà réalisée.',[p(102,"Kal'Shebbol:",'Torize:')]),
  planet(BOOK,'Torize','place-torize','Monde industriel majeur de la route Trition, marqué par le volcanisme et une catastrophe industrielle.','La population est donnée à 1,5 milliard au début de la campagne. L’atmosphère de type II justifie des masques respiratoires ; activité volcanique et polluants libérés trois ans auparavant la dégradent. Stations orbitales et astroports soutiennent les échanges. En retraite, Sarne renforce sa flotte avec des appareils de la défense planétaire.',[p(102,'Torize:','Kolatill:')]),
  planet(BOOK,'Kolatill','place-kolatill','Centre de fabrication de répulseurs sur la route Trition, important pour les véhicules terrestres et atmosphériques.','Le monde compte environ 400 millions d’habitants et a subi la loi martiale de Sarne. Son industrie présente un intérêt stratégique pour la Nouvelle République. L’aventure Omens développe sa situation.',[p(102,'Kolatill:','Brolsam:')]),
  planet(BOOK,'Brolsam','place-brolsam','Monde agricole proche de Kal’Shebbol, mais éloigné de la grande route et faiblement peuplé.','Le livre indique environ quinze millions d’habitants répartis à peu près également entre Humains, Rodiens et Fefze. Les Fefze participent largement au développement agricole ; festivals, sculpture et chant ont attiré une communauté artistique.',[p(102,'Brolsam:'),p(103,undefined,'Aaris:')]),
  planet(BOOK,'Aaris','place-aaris','Système éloigné non colonisé ayant reçu au moins une expédition scientifique.','Le dossier introductif renvoie à Artifact of Aaris pour développer l’expédition et les découvertes. Le nom du système n’autorise pas à attribuer automatiquement toutes ses données à un monde précis.',[p(103,'Aaris:','Chans:')]),
  planet(BOOK,'Charis','place-charis','Monde industriel et informatique dont le soulèvement contre Sarne a été écrasé.','La population, proche d’un milliard avant la répression quatre ans auparavant, est évaluée à environ 850 millions. Des villes sont devenues des ruines bombardées. Des sympathisants républicains seraient prêts à une nouvelle révolution, mais attendent des encouragements : il s’agit d’une possibilité, pas d’une libération accomplie.',[p(103,'Chans:','Oon Tien:')]),
  planet(BOOK,'Oon Tien','place-oon-tien','Monde montagneux et humide des Jarells, abritant les principaux chantiers navals impériaux du secteur.','Les monarchies jarells échangent gemmes et travail sous contrat de jeunes sujets contre des technologies, notamment des armes. Les changements politiques violents restent initialement internes à leur société. Industrie et agriculture prennent ensuite de l’importance.\n\nTrois docks orbitaux peuvent réparer des bâtiments jusqu’à 300 mètres. Le gouverneur Manon Flint reçoit l’ordre de les tenir ou de les détruire plutôt que les céder. Mines, patrouilleurs IPV et chasseurs TIE forment une défense strictement locale, permettant de soutenir la flotte de Sarne.',[p(103,'Oon Tien:'),p(104,undefined,'Coijain:')]),
  planet(BOOK,'Corjain','place-corjain','Monde minier riche en métaux mais doté d’une atmosphère toxique, habité dans des complexes souterrains.','Les communautés twi’leks, jarells et svivreni exploitent des mines dangereuses et lucratives. Secret MJ : un poste d’écoute bothan surveille le FarStar et le gouvernement de Kal’Shebbol sans que la Nouvelle République le sache.',[p(104,'Coijain:','Gandle Ott:')]),
  planet(BOOK,'Gandle Ott','place-gandle-ott','Dernier grand monde industriel du secteur, dans le système Ott, partagé entre sympathies impériales et républicaines.','Sa population se compte en milliards et sa relative autosuffisance lui donne un rôle politique déterminant. Death is Remotely Possible exploite l’incertitude de ses orientations lors de l’arrivée prévue du FarStar.',[p(104,'Gandle Ott:','Maime,')]),
  planet(BOOK,'Shintel','place-shintel','Au-delà de Gandle Ott, un système réputé vide cache une base impériale de ravitaillement et de patrouille.','La réputation d’absence d’habitants ne décrit pas la réalité militaire. Le site constitue le cadre de Shintel Downtime.',[p(105,'Shintel:','Pembric II:')]),
  planet(BOOK,'Pembric II','place-pembric','Monde semi-indépendant de contrebandiers et criminels, contrôlé par la Pembric Security Legion.','La légion se distingue des autres organisations criminelles par uniformes et badges, sans que cela en fasse une autorité républicaine. L’aventure Crisis développe ce cadre.',[p(105,'Pembric II:','Galtea:')]),
  planet(BOOK,'Galtea','place-galtea','Petite colonie non alignée offrant surtout vivres et fournitures de base.','Le marchand Veild-danol peut y être rencontré. Le monde est développé dans Traitor in Our Midst.',[p(105,'Galtea:','Sebiris:')]),
  planet(BOOK,'Sebiris','place-sebiris','Monde peu technologisé situé à la bordure du secteur de Kathol.','Le dossier régional renvoie à Traitor in Our Midst pour son rôle dans la campagne ; aucune population ou infrastructure supplémentaire n’est déduite ici.',[p(105,'Sebiris:')]),
  planet(OUTBACK,'Timbra Ott','place-timbra-ott','Ancienne colonie sœur de Gandle Ott, devenue colonie pénitentiaire puis société autonome après son abandon par l’Empire.','Des séismes et raz-de-marée détruisent les colonies côtières. Kal’Shebbol installe des camps pénaux pour reconstruire les infrastructures ; l’Empire abandonne ensuite les détenus. Après émeutes et famines, une société autosuffisante se forme.\n\nLe commerce et la contrebande sont ouverts, mais la police protège les habitants. Deux générations sont nées depuis les dernières déportations : le stigmate criminel est trompeur. Un mouvement encore faible souhaite chasser les contrebandiers et pourrait s’allier à la Nouvelle République. Timbra Ott se trouve au terme de la Galtea Run.',[p(6,'## TIMBRAOTT','## THE PIMBRE')]),
  planet(OUTBACK,'Dolstan','place-dolstan','Premier monde de la Ligue pimbrellane et principal producteur de nourriture grâce à l’irrigation.','Savanes, déserts et grands lacs salés composent ce monde sec dont les sols irrigués sont fertiles. Son ancienneté lui donne une position dominante dans la politique de la Ligue. Dolstan, Swedlan et Bresan sont trois mondes de systèmes distincts : ils ne doivent pas être fusionnés en une seule planète.',[p(6,'## THE PIMBRE')]),
  planet(OUTBACK,'Swedlan','place-swedlan','Colonie de la Ligue pimbrellane dont l’atmosphère n’est pas directement respirable pour les Humains.','Masques respiratoires, dômes et habitats souterrains rendent la colonisation possible ; une part importante des ressources entretient le support vital. La Ligue privilégie autonomie, éducation et modestes industries locales.',[p(6,'## THE PIMBRE'),p(7,undefined,'## SAPELLA')]),
  planet(OUTBACK,'Bresan','place-bresan','Colonie peu hospitalière de la Ligue pimbrellane, dépendante d’installations de support vital.','Comme sur Swedlan, les habitants utilisent des masques et vivent sous dômes ou dans des complexes souterrains. Les trois mondes maintiennent ensemble une petite flotte de corvettes contre pirates et esclavagistes.',[p(6,'## THE PIMBRE'),p(7,undefined,'## SAPELLA')]),
  planet(OUTBACK,'Sapella','place-sapella','Monde entrant dans une glaciation, dont la colonie exploite une bande équatoriale encore tempérée.','Les colons vivent sur des îles côtières vallonnées et produisent fruits, grains, bétail et vin pour acquérir des fournitures. Un trajet de cinq jours depuis Timbra Ott est mentionné par la source ; cette durée ne permet pas de déduire une distance géométrique. Un pacte de défense lie les deux mondes. Deux anciens bâtiments lourds demeurent ; un troisième a été perdu dans une collision accidentelle avec les Aing-Tii, cause que le gouvernement ignore.',[p(7,'## SAPELLA','## BINAROS')]),
  planet(OUTBACK,'Binaros','place-binaros','Jeune monde sauvage riche en végétation et animaux, sans formes de vie intelligentes identifiées dans ce dossier.','Des plantes comestibles peuvent ravitailler le FarStar. Plant Food développe les circonstances et les dangers de cette ressource : la possibilité de ravitaillement n’est pas un stock déjà acquis.',[p(7,'## BINAROS','## JANGELLE')]),
  planet(OUTBACK,'Jangelle','place-jangelle','Colonie de réfugiés sur un monde chaud de plaines sableuses, rivières et deltas.','La colonie entretient des voyages discrets vers Gandle Ott et Pembric II pour obtenir les pièces nécessaires aux installations vitales. Elle connaît surtout la propagande impériale et peut se méfier de la Nouvelle République.\n\nUne économie largement autosuffisante, des transports armés, canons ioniques de défense, satellites et générateurs soutiennent le monde. Jangelle partage un pacte de défense avec la République de Kathol ; ses deux bâtiments lourds complètent les corvettes de cette dernière.',[p(7,'## JANGELLE'),p(8,undefined,'## DAYARK')]),
  planet(OUTBACK,'Dayark','place-dayark','Monde agricole le plus peuplé de la République de Kathol et siège de son gouvernement.','La République rassemble plusieurs planètes pour assurer leur protection mutuelle. Little Empires développe les implications politiques de Dayark.',[p(8,'## DAYARK','## PITANN')]),
  planet(OUTBACK,'Pitann','place-pitann','Monde désertique difficile, membre de la République de Kathol, vivant essentiellement de ses mines.','Les habitants sont décrits comme réservés et peu accueillants envers les étrangers. Le monde est détaillé dans Little Empires.',[p(8,'## PITANN','## EHJENLA')]),
  planet(OUTBACK,'Ehjenla','place-ehjenla','Monde sortant d’une longue glaciation, peuplé par les Tuhgri qui refusent la propriété individuelle.','Grandes calottes, océans profonds, plaines fertiles et fjords témoignent des anciens glaciers. Les Tuhgri attribuent leurs ressources au Grand Créateur : chacun emprunte ce dont il a besoin jusqu’à ce qu’il n’en ait plus l’usage. Les incompréhensions avec les autres sociétés ont conduit plusieurs mondes à leur interdire l’accès.',[p(8,'## EHJENLA'),p(9,undefined,'## UUKAABLIS')]),
  planet(OUTBACK,'Uukaablis','place-uukaablis','Monde accueillant, menacé par la Confédération Qektoth, dont les habitants disposent de connaissances médicales précieuses.','Les Uukaabliens ne possèdent pas encore d’hyperpropulsion mais peuvent apporter une aide médicale à la Nouvelle République. Wildfire développe ce contexte.',[p(9,'## UUKAABLIS','## SHATUUN')]),
  planet(OUTBACK,'Shatuun','place-shatuun','Montagnes et orages électriques dominent ce monde rarement visité sur la route vers Danoor.','Un couple de Duinuogwuins s’y est installé pour se reproduire. Les dragons des étoiles veulent garder leur présence secrète, mais pourraient recevoir des visiteurs garantissant leur tranquillité.',[p(9,'## SHATUUN','## EXOCRON')]),
  planet(OUTBACK,'Exocron','place-exocron','Monde caché par une nébuleuse brouillant les senseurs et absent des cartes normalement obtenues par le FarStar.','La plupart des habitants de l’Outback ignorent son existence. The Masters of Exocron développe sa découverte ; la référence ne permet pas d’attribuer au FarStar une connaissance préalable de sa position.',[p(9,'## EXOCRON','## DANOOR')]),
  planet(OUTBACK,'Danoor','place-danoor','Ancien poste scientifique d’étude du Rift, ravagé trente ans auparavant par un impact d’astéroïde.','Fondée environ un siècle auparavant, la colonie attire ensuite des habitants pour sa beauté et ses ressources. L’impact tue des centaines de milliers de personnes. La reconstruction et les rares contacts expliquent les lacunes des informations extérieures ; Galaxy’s Edge détaille la situation.',[p(9,'## DANOOR','## SUPPI')]),
  planet(ENDGAME,'Kathol','place-kathol','La planète dite DarkStryder porte en réalité le nom des anciens Kathol, spécialistes des technologies biologiques.','### Avant le désastre\nLes Kathol développent des constructions, ordinateurs et vaisseaux organiques. Le Codex, conçu pour étudier la Force, attire un Jedi sombre qui les asservit. Des Jedi tentent de les libérer.\n\n### Naissance du Rift\nLa surcharge d’une porte de lancement biologique déforme l’hyperespace et crée le Rift, tuant le Jedi sombre et contaminant la région du côté obscur. Une autre porte endommagée demeure en orbite. Une fraction des Kathol conserve essences et esprits dans le Lifewell ; la majorité meurt.\n\n### Le gardien\nUn gardien génétiquement conçu préfère dominer plutôt que libérer ceux qu’il devait préserver. Il apprend à alimenter les machines par l’énergie du Lifewell. Les esprits enfermés perçoivent et influencent la Force, mais leurs facultés se dégradent avec le temps. Ces secrets ne sont pas connus d’emblée des voyageurs.',[p(25),p(26,undefined,'## Kathol')]),
  entry(RIFT,'Kathol Rift','Location','Anomalie énergétique extrêmement dangereuse traversée par des corridors mouvants que les Aing-Tii savent détecter.','Les courants changent parfois plusieurs fois par jour. Particules, rayonnements et tempêtes dégradent boucliers, armes, senseurs et communications ; les micro-sauts risquent de sortir dans une zone mortelle. Des poches autour de certaines planètes abritent une vie fragilisée.\n\nMakezh, formé par les Aing-Tii, ressent les routes sûres plutôt que de les calculer conventionnellement. Le livre permet au MJ de supposer sa réussite pour la traversée scénarisée, sans rendre le Rift inoffensif.',[p(7)],undefined),
  entry(RIFT,'Navigation dans le Kathol Rift','Mechanic','Les sauts du Rift imposent des difficultés élevées et une spécialisation propre ; les corridors n’annulent pas tous les dangers.','Le tableau distingue micro-sauts courts, moyens, longs et sauts standards. Sans spécialisation astrogation: Kathol Rift, les tests de navigation et pilotage augmentent d’au moins trois niveaux. Sortir d’un corridor sûr expose le navire à des décharges d’énergie très destructrices. À l’intérieur même des corridors, portée et puissance des armes, boucliers, senseurs et communications sont dégradés.',[p(8)],undefined,'RULES','rules'),
  entry(OUTBACK,'Ligue pimbrellane','Faction','Trois colonies pinacistes forment un réseau autonome au terme de la Sebiris Run, au-delà du Marcol Void.','Dolstan, Swedlan et Bresan sont dans des systèmes différents. Le pinacisme attend que les spectateurs des grands événements de l’histoire puissent en recueillir les débris. Les dirigeants éduqués surveillent discrètement l’actualité galactique grâce à un drone hebdomadaire obtenu via des agents sur Gandle Ott. Une flotte commune protège les mondes ; le débat porte sur la signification de la chute de l’Empire dans leurs croyances.',[p(6,'## THE PIMBRE'),p(7,undefined,'## SAPELLA')]),
];
const riftWorlds=[
  planet(RIFT,"Q'Maere",'place-qmaere','Ancienne station scientifique convertie clandestinement par Sarne en prison et centre de rééducation.','Le docteur Kraay propose un traitement de la contamination alimentaire et des provisions, tout en évitant les questions précises. La recherche en planétologie laisse place à des prisonniers qualifiés de patients. Six dômes reliés en hexagone abritent administration et punitions, botanique, logements du personnel, deux blocs de détention et maintenance.\n\nLes tubes transportent personnes, air, eau et énergie, avec portes contrôlables à distance. Arrêter les générateurs menace particulièrement les prisonniers, privés d’une autre alimentation. Le vocabulaire administratif et médical dissimule le rôle réel de la station.',[p(27),p(28)]),
  planet(RIFT,'Yvara','place-yvara','Monde des Yvarema, conscience collective mammalienne dont Gunthar a été séparé.','Yvara orbite une étoile bleu-blanc ; les Horns of Waryl, trois étoiles en pyramide inversée, servent de repère culturel. Gunthar a été capturé loin de son peuple et vendu aux arènes de Sarne. Les Qektoth ont obtenu ses données biologiques et cherchent à retrouver les Yvarema pour leur recherche sur l’esprit-ruche.\n\nMontagnes côtières, plaines de champignons, déserts et réseaux de rivières entourent les habitats souterrains. Des technologies de vapeur et de fluidique produisent peu de pollution et peu de signatures électromagnétiques ; l’absence de signaux apparents ne signifie donc pas absence de civilisation.',[p(73),p(74)]),
  planet(RIFT,'Demonsgate','place-demonsgate','Monde proche de la sortie du Rift, dont l’apparence enflammée masque une biosphère viable.','Particules ionisées et débris du Rift rayonnent en rouge, orange et jaune, donnant l’illusion de flammes. L’eau est surtout souterraine et de nombreuses créatures creusent jusqu’à ses réserves. Le scénario approche cette planète alors que Makezh devient instable sous la compulsion aing-tii liée au Codex ; cette situation appartient au déroulement prévu, pas au présent de la partie.',[p(89,"## ADVENT'URE BACKGROUND")]),
  entry(RIFT,'Construction extraterrestre','Location','Structure biologique ancienne dont un mécanisme d’amarrage défaillant menace de saisir et broyer le FarStar.','La station sphérique, endommagée, porte dômes et vrilles semblables à des plantes. Le corridor du Rift force une approche ; le livre prévoit que les vrilles capturent le bâtiment. Elles ne constituent pas une arme militaire intentionnelle : le MJ sait qu’il s’agit d’un dispositif d’amarrage automatisé défectueux.\n\nRestes végétaux et semences suggèrent un centre civil de préparation à un programme spatial ou colonial, autrefois autosuffisant. Une relation avec DarkStryder est suggérée, mais l’espèce bâtisseuse et la fonction exacte doivent rester mystérieuses pour les joueurs.',[p(59,'## ADVENTURE','## THE SET-UP'),p(60,'## GAMEMASTER','Again, gamemasters')],{kind:'entity',id:'place-construct'}),
  entry(RIFT,'Harm’s Way','Adventure','Une contamination alimentaire née des énergies du Rift pousse le FarStar à chercher du secours sur Q’Maere.','### Déclencheur\nUne bactérie mutée détruit les provisions, y compris progressivement les aliments réfrigérés. Une ultime réserve sous vide fournit un bref répit ; l’isolement des compartiments ne suffit pas, les mutations apparaissant partout.\n\n### Urgence et choix\nLes données venues de Nah’Malis indiquent un poste de l’université de Sanbra sur Q’Maere, plus proche qu’une autre colonie située loin derrière. L’offre de ravitaillement doit engager une rencontre avec le centre de rééducation. La contamination, la famine et les incidents du calendrier restent des événements proposés par cette aventure.',[p(25)],undefined,'NARRATIVE'),
  entry(RIFT,'Rogue Elements','Adventure','Les séquelles des traitements de Q’Maere transforment Lowen Chase en meneur paranoïaque et menacent le FarStar de mutinerie.','Les anciens captifs aggravent la promiscuité et certains reconnaissent surtout l’autorité de Chase. Le MJ doit préparer quels postes commandent chaque fonction, où transférer les contrôles et quels stocks restent accessibles selon les compartiments tenus. L’aventure met ainsi les salles, ressources, loyautés et traumatismes en relation, sans activer automatiquement une mutinerie dans l’état de partie.',[p(43,'## INTRODUCTION','## EPISODE ONE')],undefined,'NARRATIVE'),
  entry(RIFT,'Waystation','Adventure','Une station biologique saisit le FarStar et impose une exploration de ses installations anciennes.','Le vaisseau peut temporairement tenir sa position mais fatigue ses moteurs. Des membres de sécurité, d’ingénierie et du commandement doivent gagner la structure, dont les sas organiques et les vrilles réagissent aux émissions énergétiques. Comprendre le mécanisme de capture compte davantage que supposer une attaque délibérée.',[p(59,'## ADVENTURE','## EPISODE DNE')],undefined,'NARRATIVE'),
];
export const entries=[...initialEntries.map(e=>({...e,site:correctedBindings[e.name]||e.site})),...roomRecords.map(([name,id,page,start,end,summary,content])=>entry(BOOK,'FarStar — '+name,'Location',summary,content,[p(page,start,end)],room(id))),...additionalRooms,...biographies,...development(RIFT,riftCrew),...development(ENDGAME,endgameCrew),...worlds,...riftWorlds];
